/* PaintPlan service worker (classic) — generated by build.mjs; BUILD is a content hash of this deploy,
   so every deploy that changes anything gets a new cache automatically (no manual version bump).
   Strategy: pages (navigations/HTML) = network-first with offline fallback to the cached copy;
   static assets (icons, manifest) = stale-while-revalidate. */
const BUILD = '036cf00ff0f7';
const PREFIX = 'paintplan-classic-';
const VERSION = PREFIX + BUILD;
const LEGACY = ["paintplan-v1"];     // cache names used by older service workers of this app
const EXCLUDE = ["proposals/","preview/"];   // sub-paths of this scope that this worker must not handle (e.g. previews with their own SW)
const SHELL = ['./', './index.html', './manifest.webmanifest', './apple-touch-icon.png', './icon-192.png', './icon-512.png'];
const SCOPE = new URL(self.registration.scope);
const NET_TIMEOUT = 4000;      // slow network: answer from cache after this, keep updating in the background

self.addEventListener('install', e => {
  e.waitUntil(caches.open(VERSION)
    .then(c => c.addAll(SHELL.map(u => new Request(u, { cache: 'reload' }))))
    .then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => LEGACY.includes(k) || (k.startsWith(PREFIX) && k !== VERSION)).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

self.addEventListener('message', e => {
  if (e.data && e.data.type === 'build' && e.ports[0]) e.ports[0].postMessage({ build: BUILD });
});

const pageKey = url => { const u = new URL(url); u.search = ''; u.hash = ''; if (u.pathname.endsWith('/index.html')) u.pathname = u.pathname.slice(0, -10); return u.href; };

async function networkFirst(req) {
  const cache = await caches.open(VERSION);
  const key = pageKey(req.url);
  const net = fetch(req.url, { cache: 'no-cache', credentials: 'same-origin' }).then(res => {
    if (res.ok && res.type === 'basic' && !res.redirected) cache.put(key, res.clone());
    return res.redirected ? Response.redirect(res.url, 302) : res;
  });
  const cached = () => cache.match(key).then(r => r || cache.match('./')).then(r => r || caches.match(key));
  let timer;
  const slow = new Promise(res => { timer = setTimeout(() => cached().then(r => r && res(r)), NET_TIMEOUT); });
  try {
    return await Promise.race([net, slow]);
  } catch (err) {
    const r = await cached();
    return r || Response.error();
  } finally { clearTimeout(timer); }
}

async function staleWhileRevalidate(e, req) {
  const cache = await caches.open(VERSION);
  const hit = await cache.match(req);
  const net = fetch(req).then(res => { if (res.ok && res.type === 'basic') cache.put(req, res.clone()); return res; });
  if (hit) { e.waitUntil(net.catch(() => {})); return hit; }
  return net;
}

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || !url.pathname.startsWith(SCOPE.pathname)) return;
  const rel = url.pathname.slice(SCOPE.pathname.length);
  if (EXCLUDE.some(p => rel.startsWith(p))) {                // not ours (e.g. a preview with its own SW): never cache it,
    if (req.mode === 'navigate') e.respondWith(fetch(req.url, { cache: 'no-cache', credentials: 'same-origin' }).then(r => r.redirected ? Response.redirect(r.url, 302) : r));
    return;                                                   // and revalidate pages so a stale HTTP-cached copy is never shown
  }
  const isPage = req.mode === 'navigate' || (req.headers.get('accept') || '').includes('text/html') || rel === '' || rel.endsWith('.html');
  if (isPage) e.respondWith(networkFirst(req));
  else if (rel === 'sw.js') return;
  else e.respondWith(staleWhileRevalidate(e, req));
});
